import{_ as t,b as l,c as r,g as o}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"自然语言处理","description":"","frontmatter":{"title":"自然语言处理","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/23.md","filePath":"articles/ai/books/ai-modern-approach/23.md"}'),a={name:"articles/ai/books/ai-modern-approach/23.md"};function s(n,i,e,d,g,_){return l(),r("div",null,[...i[0]||(i[0]=[o('<p>第 23 章介绍自然语言处理的基础方法，涵盖语言模型、句法分析和机器翻译等经典任务。重点包括：</p><h2 id="语言模型" tabindex="-1">语言模型</h2><ul><li><strong>N-gram 模型</strong>：基于前 n-1 个词预测下一个词</li><li><strong>拉普拉斯平滑（加 1 平滑）</strong>：处理未见 n-gram 的数据稀疏问题</li><li>困惑度（Perplexity）作为语言模型评价指标</li></ul><h2 id="词性标注" tabindex="-1">词性标注</h2><ul><li><strong>隐马尔可夫模型（HMM）</strong>：状态为词性，观测为单词</li><li><strong>维特比算法</strong>：求最可能的词性序列</li><li>数据稀疏问题及平滑技术</li><li>半监督学习、自训练利用未标注文本</li></ul><h2 id="句法分析" tabindex="-1">句法分析</h2><ul><li><strong>上下文无关文法（CFG）</strong>：S → NP VP 等产生式规则</li><li><strong>CYK 算法</strong>：动态规划判断句子是否被文法接受</li><li><strong>概率 CFG（PCFG）</strong>：为规则赋予概率，求最可能的句法树</li><li>评价指标：标记精确率、召回率、F1、交叉括号</li></ul><h2 id="机器翻译" tabindex="-1">机器翻译</h2><ul><li><strong>词对齐</strong>：IBM 模型 1（仅词汇翻译概率）、模型 2（增加位置信息）</li><li><strong>基于短语的翻译</strong>：克服词序差异</li><li>平行语料与单语语料的使用</li></ul><h2 id="信息抽取" tabindex="-1">信息抽取</h2><ul><li>基于模式匹配的方法（如「公司发布了产品」）</li><li>监督学习方法：标注实体和关系，设计特征（词性、依赖路径）</li><li>评价：准确率、召回率、F1</li></ul>',11)])])}const u=t(a,[["render",s]]);export{c as __pageData,u as default};
